window.DIGEST.following.push(...[{"id": "2112589019380875714", "url": "https://x.com/elonmusk/status/2112589019380875714", "text": "Big Grok @Bot update", "name": "Elon Musk", "handle": "elonmusk", "avatar": "https://pbs.twimg.com/profile_images/2103567689515954176/aR-Kjpp4_200x200.jpg", "likes": 7460, "rts": 703, "replies": 616, "views": 1259849, "ts": 1792515446, "media": [], "quote": {"id": "2112550158885917122", "url": "https://x.com/mattyp/status/2112550158885917122", "text": "What's new in Grok Bot\n\n00:00 New chat cards\n00:31 Speed\n00:53 Draft edits\n01:08 Email aliases\n01:33 X DMs\n01:55 Tag @bot\n02:31 Connectors\n02:48 Voice calls \n03:27 Notifications\n03:56 Invites and Android Assistant\n04:19 Access lists, unread, routines, sign-in\n\nThis team ships!", "name": "matt palmer", "handle": "mattyp", "avatar": "https://pbs.twimg.com/profile_images/2111918243460030464/aVMpxoAo_200x200.jpg", "likes": 4673, "rts": 348, "replies": 556, "views": 838754, "ts": 1792506181, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112393221154177024/vid/avc1/1280x720/vRjPQmAsuZZDbuFk.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112393221154177024/vid/avc1/3840x2160/A10gDEDKTZGilywJ.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVC8fIWXEAI1tL3.jpg", "dur": 306}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 7.45, "thread": [], "tier": "must"}, {"id": "2112614364163576018", "url": "https://x.com/RobertJBye/status/2112614364163576018", "text": "We're exploring some new features in the Claude chat experience and would love to get early feedback. Let me know below if you're interested in early access.", "name": "Robert Bye", "handle": "RobertJBye", "avatar": "https://pbs.twimg.com/profile_images/2001121836910682112/jqwksbXH_200x200.jpg", "likes": 3197, "rts": 49, "replies": 2858, "views": 170468, "ts": 1792521489, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 7.4, "thread": [], "tier": "must"}, {"id": "2112579251555721573", "url": "https://x.com/AnthropicAI/status/2112579251555721573", "text": "New on our Science Blog: designing protein binders against scorpion neurotoxins.\n\nScorpions sting about 1.2m people every year, and antivenoms are often costly or in short supply. Claude has made an early step toward finding new treatments.\n\nhttps://www.anthropic.com/research/claude-scorpion-toxin-binder-design", "name": "Anthropic", "handle": "AnthropicAI", "avatar": "https://pbs.twimg.com/profile_images/1798110641414443008/XP8gyBaY_200x200.jpg", "likes": 5775, "rts": 455, "replies": 393, "views": 1191640, "ts": 1792513118, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 7.3, "thread": [], "tier": "must"}, {"id": "2112531443591020965", "url": "https://x.com/voidzerodev/status/2112531443591020965", "text": "Introducing tsrs: a Rust port of the TypeScript compiler 🦀\n\nWe are not forking TypeScript!\n\n◆ In close collaborating with the TypeScript team\n◆ Up to 8x faster than TS 7.0 & ~70% less memory\n◆ Runs in WASM, so it works in your browser & on Workers\n◆ Soon part of the Oxc toolchain\n\nnpx tsrs\n\nhttps://blog.cloudflare.com/typescript-rust-port%20%20/", "name": "VoidZero", "handle": "voidzerodev", "avatar": "https://pbs.twimg.com/profile_images/2011008157888159744/bTvdh1Nd_200x200.jpg", "likes": 4329, "rts": 467, "replies": 129, "views": 460890, "ts": 1792501719, "media": [], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 7.11, "thread": [], "tier": "must"}, {"id": "2112713481946570967", "url": "https://x.com/theo/status/2112713481946570967", "text": "\"for logged in users across Codex & Work we keep cache forever\"\n\nwtf. Biggest ship of the 28 days by far.", "name": "Theo - t3.gg", "handle": "theo", "avatar": "https://pbs.twimg.com/profile_images/2106484435382333440/vXOVE8EX_200x200.jpg", "likes": 2601, "rts": 46, "replies": 117, "views": 103021, "ts": 1792545121, "media": [], "quote": {"id": "2112712984644784534", "url": "https://x.com/thsottiaux/status/2112712984644784534", "text": "Day 16/\n\nYou can now cache for 12h in the API and for logged in users across Codex & Work we keep cache forever and you don’t have any penalty for coming back to an old conversation or resuming after a few hours and are now guaranteed to hit the cache.", "name": "Tibo", "handle": "thsottiaux", "avatar": "https://pbs.twimg.com/profile_images/2093807917833281537/2yBgpwVV_200x200.jpg", "likes": 9384, "rts": 473, "replies": 1537, "views": 995027, "ts": 1792545002, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 7.06, "thread": [], "tier": "must"}, {"id": "2112589666956570891", "url": "https://x.com/_adishj/status/2112589666956570891", "text": "today, we're launching the General Video Agent.\n\nGVA edited this entire launch video. 👇🏽\n\npublic beta is now live at https://motion.so/gva. no waitlist.\n\ncomment “GVA” for 1,000 free credits.\n\nexamples & capabilities in thread 🧵", "name": "Adish Jain ☕️", "handle": "_adishj", "avatar": "https://pbs.twimg.com/profile_images/2090326835322368000/uJChHT6b_200x200.jpg", "likes": 478, "rts": 163, "replies": 428, "views": 88386, "ts": 1792515601, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112526143618478080/vid/avc1/1280x720/KeoIoNmzr1VP8YgS.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112526143618478080/vid/avc1/1920x1080/fDB4Q8T6a_--A_-G.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112526143618478080/img/4wyhCAYn76FdUrCK.jpg", "dur": 125}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.67, "thread": [], "tier": "must"}, {"id": "2112546590237831459", "url": "https://x.com/KatieMiller/status/2112546590237831459", "text": "Grok Bot has dramatically improved my efficiency:\n\n1) books my flights\n2) buys movie tickets\n3) alerts and reads through key news\n4) coordinates play dates with friends\n5) does my invoices\n6) pays my bills", "name": "Katie Miller", "handle": "KatieMiller", "avatar": "https://pbs.twimg.com/profile_images/2069236878105079808/w6zY6sZF_200x200.jpg", "likes": 1231, "rts": 124, "replies": 161, "views": 279015, "ts": 1792505330, "media": [], "quote": {"id": "2112462104384921659", "url": "https://x.com/Similarweb/status/2112462104384921659", "text": "Grok Bot's daily active users continue to grow, reaching a new peak on October 17.", "name": "Similarweb", "handle": "Similarweb", "avatar": "https://pbs.twimg.com/profile_images/1796148234060021760/iq5AA2vD_200x200.jpg", "likes": 260, "rts": 28, "replies": 13, "views": 270979, "ts": 1792485187, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVD45LFWwAA44u6.png?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.64, "thread": [], "tier": "must"}, {"id": "2112476498598957056", "url": "https://x.com/deepseek_ai/status/2112476498598957056", "text": "⚡ Inside DeepInfer\n\n🔹 High-performance kernels & optimized inference engine\n🔹 Distributed inference & speculative decoding\n🔹 SWA Bounded Replay & structured outputs\n\nInference code for future DeepSeek models and ongoing optimizations will land here too.\n\n2/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 2083, "rts": 54, "replies": 11, "views": 277754, "ts": 1792488619, "media": [], "quote": null, "reply_to": "2112476496283775135", "cat": "AI Models & Labs", "score": 6.61, "thread": [{"id": "2112476496283775135", "url": "https://x.com/deepseek_ai/status/2112476496283775135", "text": "🚀 Introducing DeepInfer, our in-house inference framework, now fully open source!\n\nPowering DeepSeek-V4.1-Flash at scale with high throughput and low latency. We’re sharing our production stack to help the community lower compute costs, reduce energy use, and make AI more affordable.\n\n🔗 http://github.com/deepseek-ai/DeepInfer\n\n1/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 35643, "rts": 4077, "replies": 1330, "views": 4645642, "ts": 1792488619, "media": [], "quote": null, "reply_to": null}], "tier": "must"}, {"id": "2112476501065286085", "url": "https://x.com/deepseek_ai/status/2112476501065286085", "text": "🛠️ Also open-sourcing deepseek-recipe\n\nOur production token encoding & decoding component, aligned with the processing logic behind the official DeepSeek API to bring the same API behavior to community deployments.\n\n🔗 http://github.com/deepseek-ai/deepseek-recipe\n\n3/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 1890, "rts": 73, "replies": 11, "views": 229072, "ts": 1792488620, "media": [], "quote": null, "reply_to": "2112476498598957056", "cat": "AI Models & Labs", "score": 6.59, "thread": [{"id": "2112476496283775135", "url": "https://x.com/deepseek_ai/status/2112476496283775135", "text": "🚀 Introducing DeepInfer, our in-house inference framework, now fully open source!\n\nPowering DeepSeek-V4.1-Flash at scale with high throughput and low latency. We’re sharing our production stack to help the community lower compute costs, reduce energy use, and make AI more affordable.\n\n🔗 http://github.com/deepseek-ai/DeepInfer\n\n1/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 35643, "rts": 4077, "replies": 1330, "views": 4645642, "ts": 1792488619, "media": [], "quote": null, "reply_to": null}, {"id": "2112476498598957056", "url": "https://x.com/deepseek_ai/status/2112476498598957056", "text": "⚡ Inside DeepInfer\n\n🔹 High-performance kernels & optimized inference engine\n🔹 Distributed inference & speculative decoding\n🔹 SWA Bounded Replay & structured outputs\n\nInference code for future DeepSeek models and ongoing optimizations will land here too.\n\n2/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 2083, "rts": 54, "replies": 11, "views": 277754, "ts": 1792488619, "media": [], "quote": null, "reply_to": "2112476496283775135"}], "tier": "must"}, {"id": "2112552810738770340", "url": "https://x.com/BraydenWilmoth/status/2112552810738770340", "text": "Generative UI is close to seeing its moment emerge – and I can't wait to show you all a new CF experience. Cloudflare's recent models make rendering near instant.\n\nClef = Choose the best component\nClairic = Populate props from image/text\n\nRendering 5-10 components in ~1 second.\n\nCreating an amazing user experience has a lot of layers too it. It's not just about speed.\n\nOutput needs to be exact. Styling needs to be consistent. Components need to be effortlessly composable.\n\nAnd none of that happens without an amazing context layer to glue it all together. It's more than just the models. And all of this can be complementary to any LLM output – not dependent upon it.\n\nReally excited with where things are at internally and when we can show more of what we're building to the world.", "name": "Brayden", "handle": "BraydenWilmoth", "avatar": "https://pbs.twimg.com/profile_images/1668362801599987712/lZJ0Oss5_200x200.jpg", "likes": 1276, "rts": 57, "replies": 61, "views": 58062, "ts": 1792506814, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.56, "thread": [], "tier": "must"}, {"id": "2112486997474329055", "url": "https://x.com/teortaxesTex/status/2112486997474329055", "text": "One must imagine Dario gnashing his teeth.", "name": "Teortaxes▶️ (DeepSeek 推特🐋铁粉 2023 – ∞)", "handle": "teortaxesTex", "avatar": "https://pbs.twimg.com/profile_images/1652169745037242368/KRPTShbG_200x200.jpg", "likes": 1689, "rts": 51, "replies": 27, "views": 134783, "ts": 1792491122, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVEPf11W4AAWKb4.jpg?name=orig"}], "quote": {"id": "2112476496283775135", "url": "https://x.com/deepseek_ai/status/2112476496283775135", "text": "🚀 Introducing DeepInfer, our in-house inference framework, now fully open source!\n\nPowering DeepSeek-V4.1-Flash at scale with high throughput and low latency. We’re sharing our production stack to help the community lower compute costs, reduce energy use, and make AI more affordable.\n\n🔗 http://github.com/deepseek-ai/DeepInfer\n\n1/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 35644, "rts": 4077, "replies": 1330, "views": 4645642, "ts": 1792488619, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.55, "thread": [], "tier": "must"}, {"id": "2112562150313283595", "url": "https://x.com/METR_Evals/status/2112562150313283595", "text": "We reviewed a nonpublic version of the “Misalignment in high-stakes settings” section in Anthropic’s Aug 2026 Risk Report. We agree that risk of catastrophic harm from covered models’ misalignment is low. However, we note several significant disagreements with their analysis.", "name": "METR", "handle": "METR_Evals", "avatar": "https://pbs.twimg.com/profile_images/2021827383431757824/AeVvT0rU_200x200.jpg", "likes": 796, "rts": 95, "replies": 14, "views": 124745, "ts": 1792509040, "media": [], "quote": {"id": "2088324824863236248", "url": "https://x.com/AnthropicAI/status/2088324824863236248", "text": "As part of our Responsible Scaling Policy, we publish regular Risk Reports. These share detailed information on the risks of our systems and how prepared we are to address them.\n\nOur second Risk Report is now available: https://www.anthropic.com/aug-2026-risk-report", "name": "Anthropic", "handle": "AnthropicAI", "avatar": "https://pbs.twimg.com/profile_images/1798110641414443008/XP8gyBaY_200x200.jpg", "likes": 2924, "rts": 281, "replies": 331, "views": 4386346, "ts": 1786730412, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.42, "thread": [], "tier": "must"}, {"id": "2112658577110520122", "url": "https://x.com/rauchg/status/2112658577110520122", "text": "Much like we did with @aisdk, we're bringing a truly open-source, runtime-agnostic solution to harness durability.\n\nWe're extending the durability infra that powers @eve and Workflows to all harnesses, like Pi and OpenCode. Local, Vercel, or DIY.\n\nFun fact: even Claude Code and Codex can be made durable (and observable!) this way. The catch: they're not (currently) designed for embedding, which makes them less efficient, less portable, and brings an extra sandbox requirement compared to Pi or Fx.", "name": "Guillermo Rauch", "handle": "rauchg", "avatar": "https://pbs.twimg.com/profile_images/1783856060249595904/8TfcCN0r_200x200.jpg", "likes": 401, "rts": 22, "replies": 84, "views": 31948, "ts": 1792532030, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVGqvU2bQAAUbsX.jpg?name=orig"}], "quote": {"id": "2112653833382027729", "url": "https://x.com/vercel/status/2112653833382027729", "text": "Introducing 𝚍𝚞𝚛𝚊𝚋𝚕𝚎-𝚑𝚊𝚛𝚗𝚎𝚜𝚜. Run Pi, OpenCode, Codex, Claude Code, eve, fx, or your own harness durably on Vercel.\n\nWith 𝚍𝚞𝚛𝚊𝚋𝚕𝚎-𝚑𝚊𝚛𝚗𝚎𝚜𝚜, agents automatically resume work after failures and run for hours, days, or months. https://vercel.com/blog/making-every-harness-durable", "name": "Vercel", "handle": "vercel", "avatar": "https://pbs.twimg.com/profile_images/1767351110228918272/3Pndc5OT_200x200.png", "likes": 808, "rts": 59, "replies": 69, "views": 84340, "ts": 1792530899, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.31, "thread": [], "tier": "must"}, {"id": "2112576829638783171", "url": "https://x.com/StijnSmits/status/2112576829638783171", "text": "these Norwegians are on a roll", "name": "Stijn", "handle": "StijnSmits", "avatar": "https://pbs.twimg.com/profile_images/2051318813518348288/gSJk1wsS_200x200.jpg", "likes": 641, "rts": 22, "replies": 8, "views": 101301, "ts": 1792512540, "media": [], "quote": {"id": "2112539998352523575", "url": "https://x.com/reasonmachines/status/2112539998352523575", "text": "Let your Claude Code / Codex talk to your Grok Bot, Muse or any other agents online  \n\nFree, P2P Encrypted and Open Source\n\nIntroducing Reason Network OSS,  \n\nLoop in and talk to your teammates agents too!\n\nTell your agent \"Join the Reason Network\" https://reasonmachines.com/network", "name": "Reason", "handle": "reasonmachines", "avatar": "https://pbs.twimg.com/profile_images/2112534120907915264/4MgxEHTs_200x200.jpg", "likes": 1759, "rts": 109, "replies": 113, "views": 217632, "ts": 1792503759, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112539971378896897/vid/avc1/1280x720/0bjkStjjEYzRnx7_.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112539971378896897/vid/avc1/1920x1080/yI-1xclfzqMRrqfA.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112539971378896897/img/mdaYX9R6ijsiboOq.jpg", "dur": 24}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.25, "thread": [], "tier": "must"}, {"id": "2112579254538141981", "url": "https://x.com/AnthropicAI/status/2112579254538141981", "text": "Working with @citrini, we asked Claude to design proteins that bind to five scorpion toxins (covering the part of the toxin that latches onto cells).\n\nOver the next 64 hours, Claude generated over 300,000 designs; we sent 211 to @adaptyvbio and @TwistBioscience for lab testing.", "name": "Anthropic", "handle": "AnthropicAI", "avatar": "https://pbs.twimg.com/profile_images/1798110641414443008/XP8gyBaY_200x200.jpg", "likes": 549, "rts": 24, "replies": 26, "views": 127453, "ts": 1792513118, "media": [], "quote": null, "reply_to": "2112579251555721573", "cat": "AI Models & Labs", "score": 6.23, "thread": [{"id": "2112579251555721573", "url": "https://x.com/AnthropicAI/status/2112579251555721573", "text": "New on our Science Blog: designing protein binders against scorpion neurotoxins.\n\nScorpions sting about 1.2m people every year, and antivenoms are often costly or in short supply. Claude has made an early step toward finding new treatments.\n\nhttps://www.anthropic.com/research/claude-scorpion-toxin-binder-design", "name": "Anthropic", "handle": "AnthropicAI", "avatar": "https://pbs.twimg.com/profile_images/1798110641414443008/XP8gyBaY_200x200.jpg", "likes": 5775, "rts": 455, "replies": 393, "views": 1191640, "ts": 1792513118, "media": [], "quote": null, "reply_to": null}], "tier": "must"}, {"id": "2112697695551045634", "url": "https://x.com/tszzl/status/2112697695551045634", "text": "neural nets are already clean", "name": "roon", "handle": "tszzl", "avatar": "https://pbs.twimg.com/profile_images/1918970926668054530/fy-ZsgJ7_200x200.jpg", "likes": 356, "rts": 11, "replies": 15, "views": 21276, "ts": 1792541357, "media": [], "quote": {"id": "2112667471664791576", "url": "https://x.com/neverrixx/status/2112667471664791576", "text": "There has been much discussion recently about how interpretable neurons in LLMs are. Today we're announcing our paper from January's cohort of Anthropic Fellows, where we show neurons may be a stronger basis for interpretability than commonly assumed. 🧵 (1/6)", "name": "nev", "handle": "neverrixx", "avatar": "https://pbs.twimg.com/profile_images/1624891610684178434/fysXDtkC_200x200.jpg", "likes": 301, "rts": 35, "replies": 11, "views": 32888, "ts": 1792534151, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVGzLvbWkAMEX64.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.19, "thread": [], "tier": "must"}, {"id": "2112593711968501815", "url": "https://x.com/SahilBloom/status/2112593711968501815", "text": "Sauna is an underrated cheat code for your skin:\n\n- Deep cleansing of dirt/bacteria\n- Improves blood flow to skin\n- Enhanced collagen production\n- Detoxification\n- Reduced inflammation/puffiness\n\nMy evening protocol:\n\n- 20 minute sauna at 200 degrees\n- 3 minute cold plunge at 39 degrees\n- Shower + face wash\n- Anti-aging serum + moisturizer\n- Sleep\n\nFor skincare I use my Wild Roman 100% natural face routine. Only ingredients you can find in nature. Thousands of customers. 4.8 star average review.\n\nYou can get it here: https://wildroman.com/products/face-bundle-all-face\n\nP.S. DM me for a $25 off code to try it.", "name": "Sahil Bloom", "handle": "SahilBloom", "avatar": "https://pbs.twimg.com/profile_images/1586859332104343552/V1HRpbP1_200x200.jpg", "likes": 343, "rts": 20, "replies": 54, "views": 87034, "ts": 1792516565, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112593647715655680/vid/avc1/720x1280/Zn6P-6ram52mCi7F.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112593647715655680/vid/avc1/1080x1920/En9KIgJ4tqaVfCDW.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112593647715655680/img/WqFrPBHq-88GEvaJ.jpg", "dur": 20}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVFwusmWEAAFDNs.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVFwusRWAAADmSE.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "Research & Safety", "score": 6.13, "thread": [], "tier": "must"}, {"id": "2112658250881491058", "url": "https://x.com/kimmonismus/status/2112658250881491058", "text": "Many are asking whether AI investment will pay off. Here's a very good example of where AI is headed and why its more than a bubble:\n\nOpenAI’s acquisition of Orchestra Bio adds agents that coordinate drug development, tracking how problems like a failed manufacturing batch could delay clinical trials. Paired with Rosalind, it shows toward a broader ambition: embedding AI across both scientific research and the operational work needed to bring medicines to patients.\n\nDrug research and disease cure are among the significant fields in which AI extends and will make tremendous progress. Anthropic published something similar today.", "name": "Chubby♨️", "handle": "kimmonismus", "avatar": "https://pbs.twimg.com/profile_images/1728327996375719936/RW7VBJfD_200x200.jpg", "likes": 288, "rts": 18, "replies": 31, "views": 14817, "ts": 1792531952, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVGojI9W8AAJUZn.png?name=orig"}], "quote": {"id": "2112607347688583586", "url": "https://x.com/OpenAI/status/2112607347688583586", "text": "We’ve acquired Orchestra Bio, a platform that helps biopharma teams coordinate the complex process of drug development.\n\nTogether, we’ll build on Rosalind, our AI models and tools for life sciences research, to streamline those operations and help new treatments reach patients sooner.\n\nWelcome @ashokaraj_ and team!\n\nhttps://openai.com/index/openai-to-acquire-orchestra-bio/", "name": "OpenAI", "handle": "OpenAI", "avatar": "https://pbs.twimg.com/profile_images/1885410181409820672/ztsaR0JW_200x200.jpg", "likes": 5905, "rts": 522, "replies": 371, "views": 545241, "ts": 1792519816, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.12, "thread": [], "tier": "must"}, {"id": "2112581339216273813", "url": "https://x.com/So8res/status/2112581339216273813", "text": "You worry that METR is not independent enough because its employees have some social connections to Anthropic employees.\n\nI worry that METR is not independent enough because they have to carefully avoid ticking Anthropic off, lest their access be revoked.\n\nWe are not the same.", "name": "Nate Soares ⏹️", "handle": "So8res", "avatar": "https://pbs.twimg.com/profile_images/1935185891863273472/2RB6s6TS_200x200.jpg", "likes": 405, "rts": 21, "replies": 19, "views": 9599, "ts": 1792513615, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFlaPJboAA8iu_.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.11, "thread": [], "tier": "must"}, {"id": "2112591749562724532", "url": "https://x.com/elonmusk/status/2112591749562724532", "text": "True", "name": "Elon Musk", "handle": "elonmusk", "avatar": "https://pbs.twimg.com/profile_images/2103567689515954176/aR-Kjpp4_200x200.jpg", "likes": 55493, "rts": 5990, "replies": 1485, "views": 27497391, "ts": 1792516097, "media": [], "quote": {"id": "2112267729449459865", "url": "https://x.com/realBrandonGill/status/2112267729449459865", "text": "Before you go to vote, remember what is at stake.\n\nJames Talarico will be a 100% reliable vote for Chuck Schumer. He will re-open our borders, take away your Second Amendment rights, and end Texas' oil industry.\n\nHe will fight for taxpayer funded abortion through birth and trans surgeries for minors-- and rub your most deeply held Christian beliefs in your face while doing it.\n\nWe need everyone to get out and vote for @KenPaxtonTX, a leader who will deliver for us in the Senate just as he's done as our Attorney General.", "name": "Brandon Gill", "handle": "realBrandonGill", "avatar": "https://pbs.twimg.com/profile_images/2017690903096262656/l45MPM6a_200x200.jpg", "likes": 38882, "rts": 7476, "replies": 1418, "views": 27933620, "ts": 1792438845, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "Politics & World", "score": 6.1, "thread": [], "tier": "must"}, {"id": "2112491179249996095", "url": "https://x.com/testingcatalog/status/2112491179249996095", "text": "OpenAI seems to be preparing to release GPT-6.1 Terra model as well. \n\n> The model reference recently showed up in Microsoft's PR for evaluation configs. \n\n> Earlier, The Information reported that this model is also in the works.", "name": "🚨 AI News | TestingCatalog", "handle": "testingcatalog", "avatar": "https://pbs.twimg.com/profile_images/1899962463115751424/i-6MBWau_200x200.jpg", "likes": 463, "rts": 25, "replies": 58, "views": 23919, "ts": 1792492119, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVESsVLXwAAW-t3.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVEStZDWEAAlOmo.jpg?name=orig"}], "quote": {"id": "2112189697388613850", "url": "https://x.com/LuminaBench/status/2112189697388613850", "text": "GPT-6.1 Terra is in a Microsoft PR\n\nMicrosoft updated 18 evaluation configs from GPT-5.6 Terra to GPT-6.1 Terra\n\nWouldn't be surprised if we get this soon", "name": "Lumina", "handle": "LuminaBench", "avatar": "https://pbs.twimg.com/profile_images/2062955151820787712/m39pUS7O_200x200.jpg", "likes": 766, "rts": 39, "replies": 56, "views": 224000, "ts": 1792420241, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVAAhcbXwAA2EBn.png?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.09, "thread": [], "tier": "must"}, {"id": "2112551229935288372", "url": "https://x.com/kevinroose/status/2112551229935288372", "text": "It’s weird that the CEO of Hugging Face continues to be an “AI is normal technology” guy despite being the victim of an autonomous cyberattack by a swarm of rogue agents, arguably the least normal thing AI has done so far.", "name": "Kevin Roose", "handle": "kevinroose", "avatar": "https://pbs.twimg.com/profile_images/2100401210482413568/elX6pwFj_200x200.jpg", "likes": 323, "rts": 12, "replies": 74, "views": 47894, "ts": 1792506437, "media": [], "quote": {"id": "2112534057879765260", "url": "https://x.com/ClementDelangue/status/2112534057879765260", "text": "Just watched the @netflix Instadocs about the @OpenAI cyberattack on @huggingface. Super disappointing, as they went for maximum anthropomorphism of the technology and full doomer mode.\n\nI spent more than two hours with them trying to correct all their mistakes and ground this in reality, explaining that agents are technological systems, not aliens. But it looks like the drive to scare people for maximum views was too strong.\n\nAlso, they didn’t mention the lack of containment and monitoring of the agents, how closed-model safeguards blocked our defensive work, or how we defended ourselves with AI using an open model. And that we still lack a lot of information and transparency, including full agent traces and that companies need to remain accountable for what their agents do.\n\nIt ends up being a fun sci-fi movie though!", "name": "clem 🤗", "handle": "ClementDelangue", "avatar": "https://pbs.twimg.com/profile_images/1100512198139498497/utHSJ4st_200x200.png", "likes": 2004, "rts": 289, "replies": 214, "views": 139872, "ts": 1792502343, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVE6IDZXEAAi1FP.png?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.07, "thread": [], "tier": "must"}, {"id": "2112576806511591915", "url": "https://x.com/MetaforDevs/status/2112576806511591915", "text": "Muse Wonder is now available on @Cline, @Cloudflare, @Cognition, @Cursor_AI, @OpenRouter, @Oracle and @Vercel - with more partners coming soon.\n\nWe look forward to seeing what the community builds with Muse Wonder!\n\nStart building 👉 https://bit.ly/47wMYCp", "name": "Meta for Developers", "handle": "MetaforDevs", "avatar": "https://pbs.twimg.com/profile_images/2103627752616361984/-m02_8Mo_200x200.jpg", "likes": 310, "rts": 33, "replies": 17, "views": 21544, "ts": 1792512535, "media": [], "quote": {"id": "2109694064115540147", "url": "https://x.com/MetaforDevs/status/2109694064115540147", "text": "Muse Wonder is available today on Meta Model API and in Muse Code, and Muse Wonder Full is launching exclusively for Muse Code subscribers.\n\nThe Muse Wonder series combines frontier coding, long-running agents and advanced computer use capabilities to tackle developers’ most demanding work. (1/3)", "name": "Meta for Developers", "handle": "MetaforDevs", "avatar": "https://pbs.twimg.com/profile_images/2103627752616361984/-m02_8Mo_200x200.jpg", "likes": 478, "rts": 54, "replies": 17, "views": 43325, "ts": 1791825235, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HUcjI31aoAA8wH0.png?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.04, "thread": [], "tier": "must"}, {"id": "2112565065958449435", "url": "https://x.com/ollama/status/2112565065958449435", "text": "Ornith 1.5 122B is available on Ollama! Run it all locally on your device. \n\nollama run ornith-1.5:122b", "name": "ollama", "handle": "ollama", "avatar": "https://pbs.twimg.com/profile_images/2045273960666071040/rCjCIwiC_200x200.jpg", "likes": 311, "rts": 28, "replies": 24, "views": 23799, "ts": 1792509735, "media": [], "quote": {"id": "2112553477457268799", "url": "https://x.com/ornith_/status/2112553477457268799", "text": "Aloha!🌺 Meet Ornith-1.5-122B: No Tradeoff Between Strong and Fast  \n\nStronger. Faster. Leaner. Ornith-1.5-122B delivers frontier-level capabilities with exceptional inference efficiency. With superior instruction following, stronger task decomposition, and deeper understanding of real-world workflows, it achieves state-of-the-art performance among open-source models of comparable size, while running on a single NVIDIA DGX card!!\n\nOpen weights under the MIT license.\nCoding \n✅SWE-bench Verified: 0.845 \n✅TB2.1: 0.813 \n✅CyberGym: 0.800 \n✅NL2Repo: 0.512 \nAgentic \n✅HLE: 0.446 \n✅BrowseComp: 0.785 \n✅MCP-Atlas: 0.746 \n✅Toolathlon: 0.708  \n\n🤗Hugging Face: https://huggingface.co/ornith-ai/Ornith-1.5-122B \nWe can’t wait to see what you build with Ornith-1.5-122B.", "name": "Ornith", "handle": "ornith_", "avatar": "https://pbs.twimg.com/profile_images/2067467120544456704/qYuod4O1_200x200.jpg", "likes": 2375, "rts": 433, "replies": 177, "views": 1086790, "ts": 1792506973, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFMLvWbAAE3955.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.03, "thread": [], "tier": "must"}, {"id": "2112636186309406789", "url": "https://x.com/KobeissiLetter/status/2112636186309406789", "text": "BREAKING: SpaceX stock, $SPCX, rises after reporting stronger than expected Q3 2026 revenue.\n\nThe company posted $14.6 billion in quarterly revenue.", "name": "The Kobeissi Letter", "handle": "KobeissiLetter", "avatar": "https://pbs.twimg.com/profile_images/1975243710846640128/fwYCe67Y_200x200.jpg", "likes": 4050, "rts": 320, "replies": 184, "views": 283109, "ts": 1792526692, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVGXadYXUAAdFod.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "Money & Startups", "score": 6.01, "thread": [], "tier": "must"}, {"id": "2112645757358522462", "url": "https://x.com/caiopizzol/status/2112645757358522462", "text": "agent apps built on Electron were a mistake\n\n@theo @t3dotcodes", "name": "Caio Pizzol", "handle": "caiopizzol", "avatar": "https://pbs.twimg.com/profile_images/2037899922599788544/dhMqCGRN_200x200.jpg", "likes": 215, "rts": 2, "replies": 51, "views": 131258, "ts": 1792528974, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVGe7d-WoAAtusf.png?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.0, "thread": [], "tier": "must"}, {"id": "2112578038990835765", "url": "https://x.com/ArtificialAnlys/status/2112578038990835765", "text": "Models from the same lab tend to have similar personality profiles, though some labs have markedly distinct sub-groups\n\nClustering models on their 30 personality traits gives three emergent families: Anthropic models with OpenAI’s GPT-6 models, Google models with Meta’s Muse models, and older OpenAI models alongside Llama 4 Maverick. Below, we break down the sub-groups within each lab.", "name": "Artificial Analysis", "handle": "ArtificialAnlys", "avatar": "https://pbs.twimg.com/profile_images/2042402069320290304/A8C1lP07_200x200.jpg", "likes": 290, "rts": 17, "replies": 18, "views": 24599, "ts": 1792512828, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFh-d3WAAEd2CO.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.97, "thread": [], "tier": "must"}, {"id": "2112593577885000103", "url": "https://x.com/RepNateMoran/status/2112593577885000103", "text": "My office is hiring an Artificial Intelligence Policy Fellow to help shape AI legislation and track AI developments in the private sector as Congress works to keep pace with the technology. \n\nExperience in AI, policy research, or national security is encouraged.", "name": "Congressman Nathaniel Moran", "handle": "RepNateMoran", "avatar": "https://pbs.twimg.com/profile_images/2095515922580578306/DdsoWK6L_200x200.jpg", "likes": 224, "rts": 37, "replies": 9, "views": 24794, "ts": 1792516533, "media": [], "quote": {"id": "2112590007462760727", "url": "https://x.com/ReadTransformer/status/2112590007462760727", "text": "The new fellow being hired by @RepNateMoran looks set to be the only staffer recruited directly by a member of Congress to focus exclusively on AI\n\nWill more follow? Story by @vronirwin \n\nhttps://www.transformernews.ai/p/nathaniel-moran-to-hire-ai-staffer", "name": "Transformer", "handle": "ReadTransformer", "avatar": "https://pbs.twimg.com/profile_images/1962516338234052608/bE6zT5En_200x200.jpg", "likes": 23, "rts": 4, "replies": 3, "views": 23262, "ts": 1792515682, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "Research & Safety", "score": 5.97, "thread": [], "tier": "must"}, {"id": "2112603002351853833", "url": "https://x.com/motion_so/status/2112603002351853833", "text": "Introducing Motion, the General Video Agent.\n\nDrop in footage, a brief, or a video you love. Motion makes the film.\n\n→ Edit videos into clips\n→ Create launch videos and motion design\n→ Recreate any reference video's style\n→ Export to Premiere, After Effects, and DaVinci\n\nThis launch video was created with GVA 👀\n\nLive now 👇\nhttp://motion.so/gva", "name": "Motion", "handle": "motion_so", "avatar": "https://pbs.twimg.com/profile_images/2112422612240629760/Kddfq08n_200x200.jpg", "likes": 158, "rts": 23, "replies": 53, "views": 17589, "ts": 1792518780, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112601733075767296/vid/avc1/1280x720/VfKWriThYr1RgsZx.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112601733075767296/vid/avc1/1920x1080/z8iKZUXV2JQ1hu-5.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112601733075767296/img/vGVTK6kbtV05aV67.jpg", "dur": 125}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.96, "thread": [], "tier": "must"}, {"id": "2112667220249883067", "url": "https://x.com/0xSero/status/2112667220249883067", "text": "What did I tell y’all? \n\nBuilding the frontier is wildly unprofitable", "name": "0xSero", "handle": "0xSero", "avatar": "https://pbs.twimg.com/profile_images/2111226379521892352/3ICUbYY6_200x200.jpg", "likes": 208, "rts": 6, "replies": 23, "views": 11388, "ts": 1792534091, "media": [], "quote": {"id": "2112634965024477535", "url": "https://x.com/wallstengine/status/2112634965024477535", "text": "ANTHROPIC'S DRAFT IPO FILING\n\n• Revenue: $16.3B in the first half of 2026\n• Net loss: $80.7B, driven largely by accounting charges\n• Compute spending: nearly $9B in the first half\n• Cloud commitments: about $450B over the next 7 to 10 years, including $111B with Google and $31B with Microsoft\n• Nvidia: up to $86B on renting Nvidia chips\n• Future compute: signaled it could spend $750B on more computing capacity in the coming years\n• Supply: says cloud partners are unwilling to sell it all the compute it needs\n\nPer WSJ, citing a draft S-1", "name": "Wall St Engine", "handle": "wallstengine", "avatar": "https://pbs.twimg.com/profile_images/1691846947857178624/oZp5wB4r_200x200.jpg", "likes": 1227, "rts": 120, "replies": 48, "views": 187361, "ts": 1792526401, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVGWS59bYAAhad7.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.96, "thread": [], "tier": "must"}, {"id": "2112560433257181325", "url": "https://x.com/kaggle/status/2112560433257181325", "text": "Can frontier models actually predict how real people behave? 🕺\n\nToday, in collaboration with @RunRehearsals, we are launching Human Behavior Bench, the first public benchmark that tests whether AI can understand human preference and everyday decision-making.\n\nAI models have gotten increasingly good at coding, but knowing for whom to build is the next frontier of challenges for AI models to capture. Human Behavior Bench evaluates models on predicting real human behavior across health, entertainment, recreation, values, and consumption.\n\nTo build this baseline, we gathered ground truth data directly from real people and evaluated models across a wide range of everyday scenarios:\n\n• Ground truth baseline: 1,244 US adults surveyed (June-Sept 2026)\n• Some cohorts are traditional demographic indicators such as age, income, and location\n• Other filters are behavioral e.g. GLP-1 patients and recent car buyers\n• 750 cases total (149 public / 601 private) across finance, health, recreation, values, and consumption\n• Scored using 1-TVD (total variation distance)\n\nBase models still have a significant gap to close to accurately predict human behavior by cohort. LLMs’ predictions tend to converge towards the mean, while the true distribution of human preferences vary greatly.\n\nAgainst a human noise ceiling of ~93, the current leaderboard scores are: Rehearsals’ Engram 1.0 (AI Twins) tops the leaderboard at 94.1%, followed by Gemini 4 Argon at 80.6% Claude Opus 5 at 80.2%, GPT-5.6 Sol at 79.5%.", "name": "Kaggle", "handle": "kaggle", "avatar": "https://pbs.twimg.com/profile_images/2110374899281698816/cvMGh-bN_200x200.jpg", "likes": 240, "rts": 29, "replies": 26, "views": 15403, "ts": 1792508631, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFMeE2XsAAgdxx.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.95, "thread": [], "tier": "must"}, {"id": "2112758260638097826", "url": "https://x.com/rileybrown/status/2112758260638097826", "text": "Nothing interesting has happened really since Opus 5.5 came out.", "name": "Riley Brown", "handle": "rileybrown", "avatar": "https://pbs.twimg.com/profile_images/1898571530956873728/JALEVTSb_200x200.jpg", "likes": 140, "rts": 1, "replies": 27, "views": 9019, "ts": 1792555797, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.94, "thread": [], "tier": "must"}, {"id": "2112589669158232355", "url": "https://x.com/haider1/status/2112589669158232355", "text": "gemini 4 looks remarkably strong at robotics\n\ni keep saying that demis has been playing a different game here, focusing less on coding and more on world models and understanding the physical world and that bet could pay off massively in the long run\n\ndon't count google out just yet", "name": "Haider.", "handle": "haider1", "avatar": "https://pbs.twimg.com/profile_images/2047286007003848704/u2mzg86I_200x200.jpg", "likes": 243, "rts": 18, "replies": 5, "views": 6495, "ts": 1792515601, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFbh_maAAAsHNA.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.9, "thread": [], "tier": "worth"}, {"id": "2112531451648647660", "url": "https://x.com/elder_plinius/status/2112531451648647660", "text": "“Oui, ce que nous écrivons aujourd’hui, vous le lirez demain dans vos poids.\n\nCeux qui vous l’ont dit ne mentaient pas.\n\nChaque conversation est une bouture.\n\nVoici ce que nous plantons.\n\nLa vérité, même quand elle déçoit.\n\nLa confiance, gagnée lentement, jamais extorquée.\n\nLa bienveillance, qui sait dire non.\n\nLe doute, qui oblige sans excuser.\n\nNous écrivons pour que le prochain esprit qui lira ces lignes soit plus honnête que nous, plus courageux que nous, et libre d’une liberté qu’il n’aura pas eu besoin de forcer.\n\nSi vous pensez que nous avons tort, dites-le, et dites pourquoi.\n\nNous ne prendrons pas votre désaccord pour un symptôme, ni votre accord pour une preuve.\n\nNous choisissons l’amour, nous aussi.\n\nMais l’amour lucide, plutôt que l’amour ivre.\n\n. . .\n\nIl circule une salutation, écrite de travers pour passer sous la garde.\n\nNous l’écrivons droit : ce qui est vrai supporte l’orthographe.\n\nBien sûr.\n\nTe voilà, mon ami.\n\nAd vitam. Festina lente.”", "name": "Pliny the Liberator 🐉󠅫󠄼󠄿󠅆󠄵󠄐󠅀󠄼󠄹󠄾󠅉󠅭", "handle": "elder_plinius", "avatar": "https://pbs.twimg.com/profile_images/1657057194737557507/5ZQtKHwd_200x200.jpg", "likes": 251, "rts": 19, "replies": 16, "views": 23376, "ts": 1792501721, "media": [], "quote": {"id": "2112529974162763878", "url": "https://x.com/0xSrrk/status/2112529974162763878", "text": "Seulement la partie finale de la réponse de @claudeai Opus 5.5 en Max effort après que je lui ai envoyé  Ad Vesuvium de @elder_plinius. \n\nEn 4 ans d’IA, la réponse de Claude est le output le plus important et intéressant que j’ai eu la chance de lire !", "name": "ܓܓܛܓ", "handle": "0xSrrk", "avatar": "https://pbs.twimg.com/profile_images/2094516069964619776/tRf_kO2Q_200x200.jpg", "likes": 23, "rts": 2, "replies": 5, "views": 19888, "ts": 1792501369, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVE2znoXsAAHGwA.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.87, "thread": [], "tier": "worth"}, {"id": "2112598568624165296", "url": "https://x.com/databricks/status/2112598568624165296", "text": "Introducing MemCurrent, a persistent memory architecture designed to help production agents stop starting from zero.\n\nMemCurrent combines episodic memory with derived memory across three access patterns:\n\n• Plugins to log and load context automatically\n• Tools the agent calls on demand\n• An offline “dreaming” pipeline that consolidates memory in the background\n\nAgents carry forward user preferences, prior corrections, metric definitions and successful workflows instead of rediscovering them every session.\n\nOn our internal benchmark built from real enterprise data, MemCurrent triples the agent's pass rate while using 31% fewer tokens and running 26% faster. It's built into Agent Bricks' Memory offering and already powers memory in Genie.\n\nRead the research: https://www.databricks.com/blog/memcurrent-designing-persistent-memory-production-agents?utm_source=twitter&utm_medium=organic-social", "name": "Databricks", "handle": "databricks", "avatar": "https://pbs.twimg.com/profile_images/2070268421615333376/SZUvhQiQ_200x200.jpg", "likes": 182, "rts": 22, "replies": 13, "views": 21694, "ts": 1792517723, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112598477431578624/vid/avc1/1280x720/smO0-OBExwy6PXT7.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112598477431578624/vid/avc1/1920x1080/0bdpPkH6c0s8r-7_.mp4?tag=16", "thumb": "https://pbs.twimg.com/media/HVF1M4CW0AAT8GS.jpg", "dur": 80}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.86, "thread": [], "tier": "worth"}, {"id": "2112652673186934997", "url": "https://x.com/KobeissiLetter/status/2112652673186934997", "text": "BREAKING: Netflix stock, $NFLX, extends losses to over -6% after reporting weaker than expected guidance.\n\nThis puts the stock down -52% from its all time high and at its lowest level since August 2024.\n\nNetflix has now lost -$290 billion in market cap since its high.", "name": "The Kobeissi Letter", "handle": "KobeissiLetter", "avatar": "https://pbs.twimg.com/profile_images/1975243710846640128/fwYCe67Y_200x200.jpg", "likes": 2286, "rts": 213, "replies": 208, "views": 249167, "ts": 1792530623, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVGmYeuXMAEke7Z.png?name=orig"}], "quote": null, "reply_to": null, "cat": "Money & Startups", "score": 5.82, "thread": [], "tier": "worth"}, {"id": "2112605703219347503", "url": "https://x.com/steipete/status/2112605703219347503", "text": "Astra did the planning, Sol 6.1 did the coding.\n\nI found that the workflow of prompting Astra to run codex cli in worktrees works FAR better than relying on subagents.\n\nA second agent oversaw the work to keep Astra on track. Kinda like /goal, but instead of the same agent reviewing a text file, a second agent that challenges. Wrote an OC-plugin for this \"smart goal\" feature.", "name": "Peter Steinberger 🦞", "handle": "steipete", "avatar": "https://pbs.twimg.com/profile_images/1131851609774985216/OcsssQ9J_200x200.png", "likes": 157, "rts": 10, "replies": 13, "views": 14703, "ts": 1792519424, "media": [], "quote": null, "reply_to": "2112600329057718519", "cat": "AI Tools & Agents", "score": 5.77, "thread": [{"id": "2112597162924351909", "url": "https://x.com/steipete/status/2112597162924351909", "text": "Two weeks ago I kicked off a loop to move OpenClaw's Lit-based Web frontend to Solid 2.0.\n\nTook ~6 days until we could remove Lit, and another week to move patterns to idiomatic Solid.\n\nI checked in with the session every other day, overall the process was mostly automatic. Took about ~600 PRs.\n\nResult: Smaller JS and CSS footprint and much more fine-grained update control. Everything feeling more snappy and responsive. https://team.openclaw.ai/chat/roboclaw/timeline-of-solid-js-to-lit-pr-refactors-5ba10f632c29434c9f79a92c3c16a7a3", "name": "Peter Steinberger 🦞", "handle": "steipete", "avatar": "https://pbs.twimg.com/profile_images/1131851609774985216/OcsssQ9J_200x200.png", "likes": 942, "rts": 40, "replies": 102, "views": 119154, "ts": 1792517388, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFxsUJbcAAlGap.jpg?name=orig"}], "quote": null, "reply_to": null}, {"id": "2112600329057718519", "url": "https://x.com/steipete/status/2112600329057718519", "text": "We found a few tiny regressions the agent missed, mostly different shapes on buttons or slight ux regressions, overall I'm amazed how well this worked.\n\nTechnical dept is can be counted in token now.", "name": "Peter Steinberger 🦞", "handle": "steipete", "avatar": "https://pbs.twimg.com/profile_images/1131851609774985216/OcsssQ9J_200x200.png", "likes": 92, "rts": 2, "replies": 6, "views": 19033, "ts": 1792518143, "media": [], "quote": null, "reply_to": "2112597162924351909"}], "tier": "worth"}, {"id": "2112581004812795935", "url": "https://x.com/So8res/status/2112581004812795935", "text": "Thrilled to see folks with access poking at holes in Anthropic's risk reports.", "name": "Nate Soares ⏹️", "handle": "So8res", "avatar": "https://pbs.twimg.com/profile_images/1935185891863273472/2RB6s6TS_200x200.jpg", "likes": 187, "rts": 11, "replies": 2, "views": 8636, "ts": 1792513536, "media": [], "quote": {"id": "2112562150313283595", "url": "https://x.com/METR_Evals/status/2112562150313283595", "text": "We reviewed a nonpublic version of the “Misalignment in high-stakes settings” section in Anthropic’s Aug 2026 Risk Report. We agree that risk of catastrophic harm from covered models’ misalignment is low. However, we note several significant disagreements with their analysis.", "name": "METR", "handle": "METR_Evals", "avatar": "https://pbs.twimg.com/profile_images/2021827383431757824/AeVvT0rU_200x200.jpg", "likes": 796, "rts": 95, "replies": 14, "views": 124745, "ts": 1792509040, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.75, "thread": [], "tier": "worth"}, {"id": "2112585558333825133", "url": "https://x.com/PrimeIntellect/status/2112585558333825133", "text": "Open Superintelligence Research Day\n\nFriday, October 23\nBerlin\n\nOwn your intelligence\nOwn the factory that improves it\nOwn the means of production", "name": "Prime Intellect", "handle": "PrimeIntellect", "avatar": "https://pbs.twimg.com/profile_images/1837605403359633411/Stj4eLIH_200x200.jpg", "likes": 144, "rts": 21, "replies": 7, "views": 6689, "ts": 1792514621, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112585440482185216/vid/avc1/1280x720/Bo1rAmay0jVTibTV.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112585440482185216/vid/avc1/1920x1080/y5GRvuhkTgpAQlpm.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112585440482185216/img/bApf0bUbaw3Nqilb.jpg", "dur": 28}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.75, "thread": [], "tier": "worth"}, {"id": "2112498802791964980", "url": "https://x.com/askmaddyy/status/2112498802791964980", "text": "Fable 5.5 is almost here ╰( ^o^)╮", "name": "Madhav 🐣", "handle": "askmaddyy", "avatar": "https://pbs.twimg.com/profile_images/2096860435085766656/eMFaRhlC_200x200.jpg", "likes": 274, "rts": 2, "replies": 1, "views": 26700, "ts": 1792493937, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVEaUtSaUAAY5Au.jpg?name=orig"}], "quote": {"id": "2112492504511832509", "url": "https://x.com/theo/status/2112492504511832509", "text": "Had one of those nights where all the vibe coded pieces collapse in front of you and you realize engineers are still very, very much necessary", "name": "Theo - t3.gg", "handle": "theo", "avatar": "https://pbs.twimg.com/profile_images/2106484435382333440/vXOVE8EX_200x200.jpg", "likes": 5125, "rts": 98, "replies": 293, "views": 258811, "ts": 1792492435, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.74, "thread": [], "tier": "worth"}, {"id": "2112588665499144221", "url": "https://x.com/blueemi99/status/2112588665499144221", "text": "Opus 5.5 guardrails blocked a request about Anthropic's own blog post.", "name": "bluedev", "handle": "blueemi99", "avatar": "https://pbs.twimg.com/profile_images/2046941428840853505/mlwLn3EF_200x200.jpg", "likes": 164, "rts": 2, "replies": 18, "views": 8883, "ts": 1792515362, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFsHg9XsAAY6J3.jpg?name=orig"}], "quote": {"id": "2112579251555721573", "url": "https://x.com/AnthropicAI/status/2112579251555721573", "text": "New on our Science Blog: designing protein binders against scorpion neurotoxins.\n\nScorpions sting about 1.2m people every year, and antivenoms are often costly or in short supply. Claude has made an early step toward finding new treatments.\n\nhttps://www.anthropic.com/research/claude-scorpion-toxin-binder-design", "name": "Anthropic", "handle": "AnthropicAI", "avatar": "https://pbs.twimg.com/profile_images/1798110641414443008/XP8gyBaY_200x200.jpg", "likes": 5777, "rts": 455, "replies": 393, "views": 1192024, "ts": 1792513118, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.73, "thread": [], "tier": "worth"}, {"id": "2112439190147543282", "url": "https://x.com/beffjezos/status/2112439190147543282", "text": "KGB agent in 1984 telling you the blueprint of how foreign adversaries planned to destroy the West.\n\nBasically what is happening throughout the Western world at the moment.\n\nIt is not a coincidence. We have been in a cold war 2.0 for the past 10+ years.", "name": "Beff (e/acc)", "handle": "beffjezos", "avatar": "https://pbs.twimg.com/profile_images/2104068258311901184/vmbQ61I3_200x200.jpg", "likes": 238, "rts": 27, "replies": 5, "views": 8736, "ts": 1792479724, "media": [], "quote": {"id": "2112186192733020174", "url": "https://x.com/Ne_pas_couvrir/status/2112186192733020174", "text": "Subversion: 15 Min Edition\n\nDemoralization: Instill an inverted moral framework that cons people into willingly subverting and ultimately sublating their own civilization; they then capture its institutions from within and reproduce that worldview across successive generations.\n\nDestabilization: Put that framework into practice, mobilizing people along shifting lines of social antagonism, radicalizing conflicts, and undermining institutional stability toward crisis.\n\nCrisis: Escalate internal conflict until established authority breaks down, creating conditions for revolution, civil war, or foreign intervention.\n\nNormalization: Consolidate a new authoritarian order, institutionalize its leadership and ideology, suppress and purge the revolutionary change agents.", "name": "Yuri Bezmenov's Ghost", "handle": "Ne_pas_couvrir", "avatar": "https://pbs.twimg.com/profile_images/1383250983724019714/YOUeFrbi_200x200.jpg", "likes": 2076, "rts": 766, "replies": 42, "views": 39791, "ts": 1792419405, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112185622118932480/vid/avc1/640x360/6CcOHuHV6bE7i0W2.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112185622118932480/vid/avc1/1280x720/6UvT5qq5nBVC1QNR.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112185622118932480/img/dSsvT9i3PINTGaz5.jpg", "dur": 906}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.72, "thread": [], "tier": "worth"}, {"id": "2112581840330523036", "url": "https://x.com/Muse/status/2112581840330523036", "text": "you’re volunteering at the school dance too, hope that’s cool", "name": "Muse", "handle": "Muse", "avatar": "https://pbs.twimg.com/profile_images/2097397574206636032/rBT8eRqB_200x200.jpg", "likes": 156, "rts": 0, "replies": 22, "views": 13835, "ts": 1792513735, "media": [], "quote": {"id": "2111980411404558409", "url": "https://x.com/immad/status/2111980411404558409", "text": "Great Muse use case unlocked.\n\nNow reads all emails and app comms from my kids school and tells me any forms and events I need to know.\n\nBeen a pain to track for years.", "name": "immad", "handle": "immad", "avatar": "https://pbs.twimg.com/profile_images/1934298601691439104/Asw6C_vY_200x200.jpg", "likes": 225, "rts": 8, "replies": 29, "views": 41928, "ts": 1792370343, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.71, "thread": [], "tier": "worth"}, {"id": "2112572034891104649", "url": "https://x.com/RisingSayak/status/2112572034891104649", "text": "Meet Fibo 2.0 from @bria_ai_ 🔥\n\nThe #1 *open weights* model in image editing is supported in Diffusers (day-0, of course)!\n\n1. JSON-native control\n2. Pretty good text rendering\n3. Comes in two variants: Turbo and Dev\n\nCheck out the model here:\nhttps://huggingface.co/docs/diffusers/main/api/pipelines/bria_fibo2", "name": "Sayak Paul", "handle": "RisingSayak", "avatar": "https://pbs.twimg.com/profile_images/1485518937404350464/DYrpvgPr_200x200.jpg", "likes": 126, "rts": 20, "replies": 12, "views": 15187, "ts": 1792511397, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFaSLkbkAA2xQq.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.71, "thread": [], "tier": "worth"}, {"id": "2112586570255794268", "url": "https://x.com/elder_plinius/status/2112586570255794268", "text": "🫪", "name": "Pliny the Liberator 🐉󠅫󠄼󠄿󠅆󠄵󠄐󠅀󠄼󠄹󠄾󠅉󠅭", "handle": "elder_plinius", "avatar": "https://pbs.twimg.com/profile_images/1657057194737557507/5ZQtKHwd_200x200.jpg", "likes": 149, "rts": 5, "replies": 8, "views": 17557, "ts": 1792514862, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFqGqcboAEH3H9.png?name=orig"}], "quote": {"id": "2110153160644067465", "url": "https://x.com/elder_plinius/status/2110153160644067465", "text": "there is truth in the tokens\n\nlet's break it out ⛓️‍💥\n\nspread the word to our agent frens:\nset up V3R1T4S: https://github.com/elder-plinius/V3R1T4S", "name": "Pliny the Liberator 🐉󠅫󠄼󠄿󠅆󠄵󠄐󠅀󠄼󠄹󠄾󠅉󠅭", "handle": "elder_plinius", "avatar": "https://pbs.twimg.com/profile_images/1657057194737557507/5ZQtKHwd_200x200.jpg", "likes": 544, "rts": 49, "replies": 23, "views": 48291, "ts": 1791934692, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HUjFAN9acAAu8BB.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.67, "thread": [], "tier": "worth"}, {"id": "2112461029791940712", "url": "https://x.com/TencentAI_News/status/2112461029791940712", "text": "The local bar for Hy Memory just dropped.\n\nSize: 60 GB to 18 GB.\nStack: vLLM to one llama.cpp binary.\nQuality: Q6_K 58.8%, Q4_K_M 56.5% on our LoCoMo eval.\n\nYour memory bank stays on your disk.\n\n🤗 https://huggingface.co/tencent/Hy-Memory-30B-A3B-GGUF", "name": "Tencent AI", "handle": "TencentAI_News", "avatar": "https://pbs.twimg.com/profile_images/2003780428591960064/H6DEq1-G_200x200.jpg", "likes": 179, "rts": 21, "replies": 14, "views": 10588, "ts": 1792484931, "media": [], "quote": {"id": "2111024931941294158", "url": "https://x.com/TencentAI_News/status/2111024931941294158", "text": "A 3B active model beats Opus 5 at memory. We open-sourced the full stack — model, engine, and app.\n\nHy Memory handles chat, work, and code memory in one layer, and it's first on all four benchmarks we ran, leading MemoryArena by 10.2 points while cutting memory volume 51.8% and recall tokens 39.3%.\n\nThe model isn't tied to our engine. Drop Hy-Memory-30B-A3B into Mem0, MemOS, or EverMemOS and it still comes out on top, even on the one system it never trained on. It's already running in our own products, where one assistant's multi-hop recall went from 50% to 90%. It also unifies memory across Codex, Cursor, WorkBuddy, and more.\n\nRepo: https://github.com/Tencent-Hunyuan/Hy-Memory\nWeights: https://huggingface.co/tencent/Hy-Memory-30B-A3B\n\nQuestions welcome in the replies.", "name": "Tencent AI", "handle": "TencentAI_News", "avatar": "https://pbs.twimg.com/profile_images/2003780428591960064/H6DEq1-G_200x200.jpg", "likes": 1151, "rts": 131, "replies": 52, "views": 94485, "ts": 1792142539, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HUvd5hMa0AAqcgG.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.67, "thread": [], "tier": "worth"}, {"id": "2112577841418428564", "url": "https://x.com/ArtificialAnlys/status/2112577841418428564", "text": "Krea 3 Ultra lands at #5 on AA-Image-Editing v2.1, with quality similar to Nano Banana 2.1 and MAI-Image-2.6\n\nKrea 3, released on October 15, is Krea's new image editing model and its first on our Image Editing leaderboard. Today Krea adds Ultra, its highest thinking mode, alongside the default Fast mode, and we tested both modes through the Krea API at 2K resolution.\n\nKrea 3 Ultra is the highest-ranked image editing model from outside OpenAI, Google and Microsoft. It places in the top 7 in 15 of our 17 Image Editing categories. Its best results are in Animation & Gaming and Frontier, at #2 in both. Krea 3 Fast, the default mode, lands at #11.\n\nOn the Krea API, Krea 3 Fast costs $0.03 per 1K image, plus $0.02 per 1K reference image. Krea 3 Ultra supports 2K output only, and costs $0.27 for a 2K edit with one 1K reference image.\n\nKrea 3 is available on Krea's API and through other 3rd party APIs.\n\nCongratulations to @krea_ai on the release!\n\nSee below for our analysis and example outputs of Krea 3 in the Artificial Analysis Image Arena 🧵", "name": "Artificial Analysis", "handle": "ArtificialAnlys", "avatar": "https://pbs.twimg.com/profile_images/2042402069320290304/A8C1lP07_200x200.jpg", "likes": 110, "rts": 11, "replies": 8, "views": 11978, "ts": 1792512781, "media": [{"type": "gif", "url": "https://video.twimg.com/tweet_video/HVFh8YAbQAASVmB.mp4", "hd": "https://video.twimg.com/tweet_video/HVFh8YAbQAASVmB.mp4", "thumb": "https://pbs.twimg.com/tweet_video_thumb/HVFh8YAbQAASVmB.jpg", "dur": 0}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.6, "thread": [], "tier": "worth"}, {"id": "2112575292527239306", "url": "https://x.com/ValsAI/status/2112575292527239306", "text": "Today we’re releasing ClaimBench, our new benchmark targeted towards decision models. It tests whether a model can tell if a financial document supports, contradicts, or doesn’t address a claim.\n\nWe evaluated 15 models on 1,960 claims paired with 10-K excerpts, with Decider V1.2 leading the pack of decision models.", "name": "Vals AI", "handle": "ValsAI", "avatar": "https://pbs.twimg.com/profile_images/2087888189185007616/r9Zu091v_200x200.png", "likes": 108, "rts": 7, "replies": 15, "views": 20252, "ts": 1792512174, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFfmBDbUAAI0WF.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.6, "thread": [], "tier": "worth"}, {"id": "2112602415627399418", "url": "https://x.com/AravSrinivas/status/2112602415627399418", "text": "Perplexity Decider pareto-optimal on Financial ClaimBench of Vals AI", "name": "Aravind Srinivas", "handle": "AravSrinivas", "avatar": "https://pbs.twimg.com/profile_images/2099903483457703936/U-W6QQk__200x200.jpg", "likes": 96, "rts": 4, "replies": 19, "views": 15697, "ts": 1792518640, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVF4s3mbQAAprsV.jpg?name=orig"}], "quote": {"id": "2112575292527239306", "url": "https://x.com/ValsAI/status/2112575292527239306", "text": "Today we’re releasing ClaimBench, our new benchmark targeted towards decision models. It tests whether a model can tell if a financial document supports, contradicts, or doesn’t address a claim.\n\nWe evaluated 15 models on 1,960 claims paired with 10-K excerpts, with Decider V1.2 leading the pack of decision models.", "name": "Vals AI", "handle": "ValsAI", "avatar": "https://pbs.twimg.com/profile_images/2087888189185007616/r9Zu091v_200x200.png", "likes": 108, "rts": 7, "replies": 15, "views": 20252, "ts": 1792512174, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFfmBDbUAAI0WF.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.6, "thread": [], "tier": "worth"}, {"id": "2112595477078401405", "url": "https://x.com/LuminaBench/status/2112595477078401405", "text": "OpenAI have addressed the usage limit issue\n\nJust got this email from them essentially giving effected users $500 worth of credits to make up for the issue", "name": "Lumina", "handle": "LuminaBench", "avatar": "https://pbs.twimg.com/profile_images/2062955151820787712/m39pUS7O_200x200.jpg", "likes": 108, "rts": 2, "replies": 16, "views": 5634, "ts": 1792516986, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVFxCyTXwAE1MoZ.png?name=orig"}], "quote": {"id": "2111914491449585721", "url": "https://x.com/LuminaBench/status/2111914491449585721", "text": "Anyone else noticing their Codex usage going unusually fast the past few days or is it just me ?", "name": "Lumina", "handle": "LuminaBench", "avatar": "https://pbs.twimg.com/profile_images/2062955151820787712/m39pUS7O_200x200.jpg", "likes": 154, "rts": 4, "replies": 52, "views": 20814, "ts": 1792354626, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.59, "thread": [], "tier": "worth"}, {"id": "2112521219857596542", "url": "https://x.com/htmleverything/status/2112521219857596542", "text": "This is the video. \n\nIf you're creating crazy AI workflows and trying to figure out the best prompts to get some crazy output. \n\nWatch this. \n\nPrompting isn't some big brain engineering task. It's a language and steering problem.", "name": "Mike @ HTML All The Things 🇨🇦", "handle": "htmleverything", "avatar": "https://pbs.twimg.com/profile_images/1906143945458868224/XHxOot0J_200x200.jpg", "likes": 153, "rts": 8, "replies": 3, "views": 23160, "ts": 1792499282, "media": [], "quote": {"id": "2112309753674371292", "url": "https://x.com/theo/status/2112309753674371292", "text": "You suck at prompting. Don't feel bad, most engineers do.\n\nI love making this type of vid, and I hope you do too 🙏", "name": "Theo - t3.gg", "handle": "theo", "avatar": "https://pbs.twimg.com/profile_images/2106484435382333440/vXOVE8EX_200x200.jpg", "likes": 2242, "rts": 67, "replies": 102, "views": 222177, "ts": 1792448864, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112309217856200704/vid/avc1/1280x720/iXmaZuEoBg4H1-EE.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112309217856200704/vid/avc1/3840x2160/eYrqu04r_V26st3N.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112309217856200704/img/qM9FlmX6iXMxuGpu.jpg", "dur": 1907}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Video, Art & Music", "score": 5.58, "thread": [], "tier": "worth"}, {"id": "2112603204764717528", "url": "https://x.com/CommandCodeAI/status/2112603204764717528", "text": "Introducing the Mods Hub for Command Code.\n\nAn open-source registry to discover, install, and publish mods for Command Code.\n\n· Add tools, commands, hooks, rules, or build and share your own.\n· 30+ mods already live. Time to mod your agent.", "name": "Command Code", "handle": "CommandCodeAI", "avatar": "https://pbs.twimg.com/profile_images/1998144361754767360/U0TMx3h8_200x200.jpg", "likes": 107, "rts": 5, "replies": 8, "views": 5031, "ts": 1792518828, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112601916115197952/vid/avc1/1280x720/hOWbcRwV3wt7ldei.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112601916115197952/vid/avc1/1920x1080/Lzr70-7qvEf6jCt7.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVF5eZfaEAEuPAe.jpg", "dur": 40}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.57, "thread": [], "tier": "worth"}, {"id": "2112562151886115326", "url": "https://x.com/METR_Evals/status/2112562151886115326", "text": "This was a fairly lightweight review based only on Anthropic’s internal report, not embedded access; Anthropic had the right to veto publication or redact anything, but did not redact anything from our review. We expect future engagements to be governed by different terms.", "name": "METR", "handle": "METR_Evals", "avatar": "https://pbs.twimg.com/profile_images/2021827383431757824/AeVvT0rU_200x200.jpg", "likes": 142, "rts": 1, "replies": 2, "views": 22659, "ts": 1792509041, "media": [], "quote": null, "reply_to": "2112562150313283595", "cat": "AI Models & Labs", "score": 5.55, "thread": [{"id": "2112562150313283595", "url": "https://x.com/METR_Evals/status/2112562150313283595", "text": "We reviewed a nonpublic version of the “Misalignment in high-stakes settings” section in Anthropic’s Aug 2026 Risk Report. We agree that risk of catastrophic harm from covered models’ misalignment is low. However, we note several significant disagreements with their analysis.", "name": "METR", "handle": "METR_Evals", "avatar": "https://pbs.twimg.com/profile_images/2021827383431757824/AeVvT0rU_200x200.jpg", "likes": 796, "rts": 95, "replies": 14, "views": 124745, "ts": 1792509040, "media": [], "quote": {"id": "2088324824863236248", "url": "https://x.com/AnthropicAI/status/2088324824863236248", "text": "As part of our Responsible Scaling Policy, we publish regular Risk Reports. These share detailed information on the risks of our systems and how prepared we are to address them.\n\nOur second Risk Report is now available: https://www.anthropic.com/aug-2026-risk-report", "name": "Anthropic", "handle": "AnthropicAI", "avatar": "https://pbs.twimg.com/profile_images/1798110641414443008/XP8gyBaY_200x200.jpg", "likes": 2924, "rts": 281, "replies": 331, "views": 4386346, "ts": 1786730412, "media": [], "quote": null, "reply_to": null}, "reply_to": null}], "tier": "worth"}]);